const sev = (x: Signal["severity"]) => x === "warning" ? "amber" : "red";
const sevWord = (x: Signal["severity"]) => html`<span class="${sev(x)}">${SEVERITY_LABEL[x]}</span>`;
const sevLabel = (x: Signal["severity"]) => html`<span class="lbl ${sev(x)}">${SEVERITY_LABEL[x]}</span>`;
// timestamps render as Pacific dates; date-only strings pass through
const fmt = (d: unknown) => { const v = s(d); if (!v) return "—"; return v.length > 10 && v.includes("T") ? new Date(v).toLocaleDateString("en-CA", { timeZone: "America/Los_Angeles" }) : v.slice(0, 10); };
const dueWord = (due: string, today: string) => { const k = daysBetween(today, due); return k < 0 ? html`<span class="red">${-k}d overdue</span>` : k === 0 ? html`<b>today</b>` : html`in ${k}d`; };
const opt = (vals: readonly string[], sel?: string, label?: Record<string, string>) => vals.map((v) => html`<option value="${v}" ${v === sel ? "selected" : ""}>${label?.[v] ?? v}</option>`);
const userOpt = (users: Row[], sel?: unknown, blank = "—") => html`<option value="">${blank}</option>${users.map((u) => html`<option value="${u.id}" ${s(u.id) === s(sel) ? "selected" : ""}>${u.name}</option>`)}`;
const stageOf = (a: Row) => STAGE_LABEL[s(a.delivery_status || a.sales_stage)];
const link = (a: Row, tab?: string) => html`<a href="/accounts/${a.id}${tab ? "?tab=" + tab : ""}">${a.name}</a>`;
const nextDated = (rel: Related) => rel.tasks.filter((t) => t.status === "open" && t.due_date).sort((p, q) => s(p.due_date).localeCompare(s(q.due_date)))[0] ?? null;

// Server-side rejections redirect with ?err=; this restores what was typed into the same form (fresh hidden version from the server), so a failed save is recoverable.
const KEEP_INPUT_JS = `(function(){var K='ccc2form';document.addEventListener('submit',function(e){var f=e.target;if(!f||f.method.toLowerCase()!=='post')return;var o={};new FormData(f).forEach(function(v,k){if(typeof v!=='string'||k==='version'||k==='passcode')return;o[k]=(o[k]!==undefined?o[k]+'\\u0000':'')+v});try{sessionStorage.setItem(K,JSON.stringify({a:f.getAttribute('action'),o:o}))}catch(_){}});
var q=new URLSearchParams(location.search);if(!q.get('err')){try{sessionStorage.removeItem(K)}catch(_){}return}var st=null;try{st=JSON.parse(sessionStorage.getItem(K)||'null')}catch(_){}if(!st)return;
document.querySelectorAll('form').forEach(function(f){if(f.getAttribute('action')!==st.a)return;Object.keys(st.o).forEach(function(k){var vals=st.o[k].split('\\u0000');f.querySelectorAll('[name="'+k+'"]').forEach(function(el){if(el.type==='hidden')return;if(el.type==='checkbox'||el.type==='radio'){el.checked=vals.indexOf(el.value)>=0}else{el.value=vals[0]}})});var d=f.closest('details');while(d){d.open=true;d=d.parentElement?d.parentElement.closest('details'):null}f.scrollIntoView({block:'center'})});try{sessionStorage.removeItem(K)}catch(_){}})();`;
export function layout(title: string, body: H, x: Ctx, opts: { counts?: { attention?: number } } = {}): H {
  const nav = (href: string, label: string, count?: number) => html`<a href="${href}" class="nav ${x.path === href || (href !== "/" && x.path.startsWith(href) && !(href === "/accounts" && x.path === "/accounts/new")) ? "on" : ""}"><span class="t">${label}</span>${count ? html`<span class="nav-count">${count}</span>` : ""}</a>`;
  const me = x.me;
  return html`<!doctype html><html lang="en"><head><meta charset="utf-8"><title>${title} · Command Center</title><meta name="viewport" content="width=device-width,initial-scale=1"><style>${raw(CSS)}</style></head><body><div class="shell">
<aside class="sidebar"><a href="/" class="brand"><span class="brand-mark">C</span><span class="t">Command Center</span></a>
${nav("/", "My work", opts.counts?.attention)}${nav("/accounts", "Accounts")}${nav("/accounts/new", "Add account")}
<div class="sidebar-bottom"><form method="post" action="/me" class="identity"><input type="hidden" name="next" value="${x.path}"><span class="avatar">${me ? initials(s(me.name)) : "?"}</span><label><small>Acting as</small><select name="me" onchange="this.form.submit()"><option value="">Pick a role</option>${x.users.map((u) => html`<option value="${u.id}" ${me && me.id === u.id ? "selected" : ""}>${u.name}</option>`)}</select></label></form></div></aside>
<main><div class="topbar"><span><b>${title}</b></span><span>Today ${fmtLong(x.today)}</span></div><div class="content">
${x.msg.err ? html`<div class="error">${x.msg.err}</div>` : ""}
${body}
</div></main></div>${x.msg.saved ? html`<div class="toast">Changes saved</div>` : ""}
<script>${raw(KEEP_INPUT_JS)}
(function(){var q=new URLSearchParams(location.search);var m=q.get('open')||(q.get('err')&&sessionStorage.getItem('ccc2_modal'));if(m){var d=document.getElementById(m);if(d&&d.showModal){d.showModal()}}document.querySelectorAll('dialog.modal form').forEach(function(f){f.addEventListener('submit',function(){try{sessionStorage.setItem('ccc2_modal',f.closest('dialog').id)}catch(_){}})});if(!q.get('err')){try{sessionStorage.removeItem('ccc2_modal')}catch(_){}}})();
</script></body></html>`;
}
export const initials = (n: string) => n.split(/\s+/).map((w) => w[0]).slice(0, 2).join("").toUpperCase();
export const fmtLong = (d: string | null | undefined) => { if (!d) return "—"; const [y, m, dd] = String(d).slice(0, 10).split("-").map(Number); if (!y || !m || !dd) return String(d); return new Date(Date.UTC(y, m - 1, dd)).toLocaleDateString("en-US", { month: "short", day: "numeric", timeZone: "UTC" }); };
export const iconClass = (name: string) => "company-icon c" + (name.length % 4);
export function modal(id: string, title: string, body: H, footer: H): H {
  return html`<dialog class="modal" id="${id}"><div class="modal-header"><h2>${title}</h2><button type="button" class="text" onclick="this.closest('dialog').close()">Close</button></div><div class="modal-body">${body}</div><div class="modal-footer"><button type="button" onclick="this.closest('dialog').close()">Cancel</button>${footer}</div></dialog>`;
}
export const openBtn = (id: string, label: string, primary = false) => html`<button type="button" class="${primary ? "primary" : ""}" onclick="document.getElementById('${id}').showModal()">${label}</button>`;

export const notFound = (): H => html`<h1>Not found</h1><p><a href="/">Back to My work</a></p>`;
export function loginPage(err?: string, next = "/"): H {
  return html`<!doctype html><html><head><meta charset="utf-8"><title>Command Center</title><style>${raw(CSS)}</style></head><body><div class="login"><div class="brand" style="margin-bottom:22px;padding:0"><span class="brand-mark">C</span><span>Command Center</span></div>
  <form method="post" action="/login"><input type="hidden" name="next" value="${next}"><label class="field"><span>Team passcode</span><input name="passcode" type="password" autofocus></label>${err ? html`<p class="ferr">${err}</p>` : ""}<button class="primary" style="width:100%">Enter</button></form></div></body></html>`;
}

// Action button for a signal: one specific next step.

function actionHref(sg: Signal, a: Row): string {
  const id = s(a.id);
  switch (sg.actionType) {
    case "decide_review": return `/reviews/${sg.subjectId}`;
    case "assign_reviewer": case "assign_technical_owner": return `/accounts/${id}?tab=overview#owners`;
    case "request_review": case "request_delivery_review": case "request_success_review": return `/accounts/${id}?tab=scope#reviews`;
    case "complete_task": return `/accounts/${id}?tab=${sg.reason.includes("milestone") ? "delivery" : "overview"}#add-action`;
    case "accept_handoff": return `/accounts/${id}/handoff`;
    case "log_meeting": return `/accounts/${id}?tab=overview#log`;
    case "add_action": return `/accounts/${id}?tab=overview#add-action`;
    case "record_requirements": return `/accounts/${id}?tab=scope#requirements`;
    case "declare_handling": case "revise_proposal": return `/accounts/${id}?tab=scope#proposal`;
    case "resolve_blocker": return `/accounts/${id}?tab=delivery#blockers`;
    case "record_outcome": return `/accounts/${id}?tab=delivery#outcome`;
    case "record_calibration": return `/accounts/${id}?tab=scope#calibration`;
    default: return `/accounts/${id}`;
  }
}
function actionFor(sg: Signal, a: Row): H {
  const id = s(a.id);
  switch (sg.actionType) {
    case "decide_review": return html`<a class="btn" href="/reviews/${sg.subjectId}">Review</a>`;
    case "assign_reviewer": case "assign_technical_owner": return html`<a class="btn" href="/accounts/${id}?tab=overview#owners">Assign technical owner</a>`;
    case "request_review": return html`<a class="btn" href="/accounts/${id}?tab=scope#reviews">Request review</a>`;
    case "complete_task": return html`<a class="btn" href="/accounts/${id}?tab=${sg.reason.includes("milestone") ? "delivery" : "overview"}#actions">Open commitment</a>`;
    case "open_account": return html`<a class="btn" href="/accounts/${id}">Open account</a>`;
    case "record_calibration": return html`<a class="btn" href="/accounts/${id}?tab=scope#calibration">Review calibration</a>`;
    case "accept_handoff": return html`<a class="btn" href="/accounts/${id}/handoff">Accept handoff</a>`;
    case "log_meeting": return html`<a class="btn" href="/accounts/${id}?tab=overview#log">Log meeting</a>`;
    case "add_action": return html`<a class="btn" href="/accounts/${id}?tab=overview#add-action">Add action</a>`;
    case "request_delivery_review": return html`<a class="btn" href="/accounts/${id}?tab=scope#reviews">Request delivery-plan review</a>`;
    case "request_success_review": return html`<a class="btn" href="/accounts/${id}?tab=scope#reviews">Request success review</a>`;
    case "record_requirements": return html`<a class="btn" href="/accounts/${id}?tab=scope#requirements">Record data restrictions</a>`;
    case "declare_handling": return html`<a class="btn" href="/accounts/${id}?tab=scope#proposal">Declare handling</a>`;
    case "resolve_blocker": return html`<a class="btn" href="/accounts/${id}?tab=delivery#blockers">Resolve blocker</a>`;
    case "record_outcome": return html`<a class="btn" href="/accounts/${id}?tab=delivery#outcome">Record outcome</a>`;
    case "revise_proposal": return html`<a class="btn" href="/accounts/${id}?tab=scope#proposal">Revise proposal</a>`;
    case "edit_account": return html`<a class="btn" href="/accounts/${id}?tab=overview#edit">Edit account</a>`;
    default: return html`<a class="btn" href="/accounts/${id}">Open</a>`;
  }
}
const nameOf = (x: Ctx, id: unknown) => x.users.find((u) => s(u.id) === s(id))?.name ?? "—";

// ---------------------------------------------------------------- My work
const TODO: Record<string, string> = { decide_review: "Decide", assign_reviewer: "Assign", assign_technical_owner: "Assign owner", request_review: "Request review", complete_task: "Open", accept_handoff: "Accept handoff", log_meeting: "Log meeting", add_action: "Add action", request_delivery_review: "Review plan", request_success_review: "Review success", record_requirements: "Record restrictions", declare_handling: "Declare handling", revise_proposal: "Revise proposal", edit_account: "Edit", resolve_blocker: "Resolve", record_outcome: "Record result", open_account: "Open", record_calibration: "Open" };
export function myWork(evals: AccEval[], x: Ctx, owner: string, view: string, query: string): H {
  const mine = (e: AccEval) => owner === "all" || s(e.a.owner_id) === owner || s(e.a.technical_owner_id) === owner;
  const qmatch = (e: AccEval) => !query || s(e.a.name).toLowerCase().includes(query.toLowerCase());
  const visible = evals.filter(mine).filter(qmatch);
  const committed = visible.flatMap((e) => e.rel.tasks.filter((t) => t.status === "open" && t.committed && !t.customer_side && (owner === "all" || s(t.owner_id) === owner || s(e.a.owner_id) === owner)));
  const overdueN = committed.filter((t) => t.due_date && s(t.due_date) < x.today).length;
  const order = { critical: 0, high: 1, warning: 2 };
  const attentionRows = visible.filter((e) => e.ev.signals.length).sort((p, q) => order[p.ev.signals[0].severity] - order[q.ev.signals[0].severity] || s(p.a.created_at).localeCompare(s(q.a.created_at)));
  const myTasks = evals.flatMap((e) => e.rel.tasks.filter((t) => t.status === "open" && (owner === "all" || s(t.owner_id) === owner)).map((t) => ({ e, t }))).sort((p, q) => (s(p.t.due_date) || "9999").localeCompare(s(q.t.due_date) || "9999"));
  const pipeline = visible.filter((e) => isPresales(e.a)), customers = visible.filter((e) => e.a.sales_stage === "won");
  const inMotion = visible.filter((e) => e.a.sales_stage !== "lost" && e.a.delivery_status !== "ended").length;
  const taskBtn = (e: AccEval, t: Row) => t.type === "review" ? html`<a class="btn" href="/reviews/${t.subject_id}">Decide</a>` : t.type === "handoff" ? html`<a class="btn" href="/accounts/${e.a.id}/handoff">Accept</a>` : html`<form method="post" action="/tasks/${t.id}/done"><input type="hidden" name="version" value="${t.version}"><input type="hidden" name="return" value="${x.path}"><button class="task-check" title="Mark done">✓</button></form>`;
  const listPanel = (title: string, rows: AccEval[], empty: string) => html`<section class="panel"><div class="section-header"><h2>${title} <span class="count">${rows.length}</span></h2></div>
    ${rows.length ? html`<div class="table-wrap"><table><thead><tr><th>Account</th><th>Stage</th><th>Owner</th><th>Next step</th><th>Attention</th></tr></thead><tbody>
    ${rows.map((e) => { const nd = nextDated(e.rel), n = e.ev.signals.length, top = e.ev.signals[0]; return html`<tr class="row-link"><td>${accountCell(e.a)}</td><td>${stageBadge(e.a)}</td><td><span class="owner-cell"><span class="avatar tiny">${initials(s(e.a.owner_name))}</span>${e.a.owner_name}</span></td><td>${nd ? html`${nd.title}<small class="sub ${s(nd.due_date) < x.today ? "late" : ""}">${fmtLong(s(nd.due_date))}</small>` : html`<span class="muted">No next step</span>`}</td><td>${n ? html`<span class="badge ${top.severity === "warning" ? "amber" : "red"}"><span class="dot"></span>${n} ${n === 1 ? "signal" : "signals"}</span>` : html`<span class="badge green"><span class="dot"></span>On track</span>`}</td></tr>`; })}</tbody></table></div>` : html`<div class="empty">${empty}</div>`}</section>`;
  return html`<div class="page-heading"><h1>My work</h1>
    <form method="get" class="tools"><select name="owner" onchange="this.form.submit()"><option value="all" ${owner === "all" ? "selected" : ""}>All team</option>${x.users.map((u) => html`<option value="${u.id}" ${owner === s(u.id) ? "selected" : ""}>${u.name}</option>`)}</select><input name="q" value="${query}" placeholder="Search accounts" size="20"><button>Search</button></form></div>
  <div class="summary-strip">
    <div><span class="summary-num">${String(inMotion).padStart(2, "0")}</span><span class="lbl">Accounts in motion<small>${pipeline.length} in presales · ${customers.length} customers</small></span></div>
    <div><span class="summary-num ${attentionRows.length ? "warm" : ""}">${String(attentionRows.length).padStart(2, "0")}</span><span class="lbl">Need attention<small>Accounts with an open signal</small></span></div>
    <div><span class="summary-num ${overdueN ? "hot" : ""}">${overdueN}<span class="denominator"> / ${committed.length}</span></span><span class="lbl">Commitments overdue<small>Promises to customers past their date</small></span></div>
  </div>
  <div class="grid2">
    <section class="panel"><div class="section-header"><h2>Needs attention <span class="count">${attentionRows.length}</span></h2></div>
      ${attentionRows.length ? attentionRows.map((e) => { const at = attention(e.ev)!, sv = at.top.severity; return html`<div class="attention-row"><span class="signal-icon ${sv === "warning" ? "amber" : "red"}">!</span><div class="attention-body"><div class="attention-title"><a href="/accounts/${e.a.id}">${e.a.name}</a>${stageBadge(e.a)}</div><p>${at.top.reason}</p><div class="attention-meta"><span>${nameOf(x, at.top.ownerId)}</span>${at.others ? html`<span>+${at.others} more</span>` : ""}</div></div><a class="btn" href="${actionHref(at.top, e.a)}">${TODO[at.top.actionType] ?? "Open"}</a></div>`; }) : html`<div class="empty">Nothing needs attention.</div>`}
    </section>
    <section class="panel"><div class="section-header"><h2>${owner === "all" ? "Open actions" : "My actions"} <span class="count">${myTasks.length}</span></h2></div>
      ${myTasks.length ? myTasks.map(({ e, t }) => html`<div class="task-row">${taskBtn(e, t)}<div><div class="task-title">${t.title}${t.committed ? html` <span class="muted">· promised</span>` : ""}</div><small><a href="/accounts/${e.a.id}">${e.a.name}</a>${owner === "all" ? html` · ${t.owner_name ?? "unowned"}` : ""}</small></div><span class="task-date ${t.due_date && s(t.due_date) < x.today ? "late" : ""}">${t.due_date ? html`${fmtLong(s(t.due_date))} · ${dueWord(s(t.due_date), x.today)}` : "no date"}</span></div>`) : html`<div class="empty">Nothing assigned.</div>`}
    </section>
  </div>
  ${listPanel("Pipeline", pipeline, "No deals in progress.")}
  ${listPanel("Customers", customers, "No signed customers.")}`;
}
export const accountCell = (a: Row) => html`<div class="account-cell"><span class="${iconClass(s(a.name))}">${initials(s(a.name))}</span><div><a href="/accounts/${a.id}">${a.name}</a>${a.contact ? html`<small>${a.contact}</small>` : ""}</div></div>`;
export const stageBadge = (a: Row) => html`<span class="badge ${a.sales_stage === "won" && ["delivery", "active"].includes(s(a.delivery_status)) ? "green" : a.sales_stage === "lost" || a.delivery_status === "ended" ? "neutral" : "neutral"}"><span class="dot"></span>${stageOf(a)}</span>`;

// ---------------------------------------------------------------- Accounts
export function accountsPage(evals: AccEval[], x: Ctx, f: { owner: string; phase: string; stage: string; attention: string; q: string }): H {
  let rows = evals;
  if (f.owner && f.owner !== "all") rows = rows.filter((e) => s(e.a.owner_id) === f.owner || s(e.a.technical_owner_id) === f.owner);
  if (f.phase === "presales") rows = rows.filter((e) => isPresales(e.a)); if (f.phase === "post") rows = rows.filter((e) => e.a.sales_stage === "won"); if (f.phase === "closed") rows = rows.filter((e) => e.a.sales_stage === "lost" || e.a.delivery_status === "ended");
  if (f.stage) rows = rows.filter((e) => s(e.a.delivery_status || e.a.sales_stage) === f.stage);
  if (f.attention) rows = rows.filter((e) => e.ev.signals.length > 0);
  if (f.q) rows = rows.filter((e) => s(e.a.name).toLowerCase().includes(f.q.toLowerCase()));
  const any = Object.values(f).some((val) => val && val !== "all");
  return html`<div class="page-heading"><h1>Accounts</h1><a href="/accounts/new" class="btn primary">Add account</a></div>
  <section class="panel"><div class="section-header"><h2>All accounts <span class="count">${rows.length}</span></h2>
    <form method="get" class="tools"><input name="q" value="${f.q}" placeholder="Search accounts" size="18"><select name="owner" onchange="this.form.submit()"><option value="all" ${f.owner === "all" ? "selected" : ""}>Any owner</option>${userOpt(x.users, f.owner, "Any owner")}</select><select name="phase" onchange="this.form.submit()">${opt(["", "presales", "post", "closed"], f.phase, { "": "All phases", presales: "Presales", post: "Post-sales", closed: "Lost / ended" })}</select><select name="stage" onchange="this.form.submit()"><option value="">All stages</option>${opt(["discovery", "proposal", "negotiation", "onboarding_pending", "delivery", "active", "lost", "ended"], f.stage, STAGE_LABEL)}</select><label class="checkbox-label" style="margin:0"><input type="checkbox" name="attention" value="1" ${f.attention ? "checked" : ""} onchange="this.form.submit()">Needs attention</label>${any ? html`<a href="/accounts" class="text">Clear</a>` : ""}</form></div>
  ${rows.length ? html`<div class="table-wrap"><table><thead><tr><th>Account</th><th>Stage</th><th>Owner</th><th>Next step</th><th>Attention</th></tr></thead><tbody>
  ${rows.map((e) => { const nd = nextDated(e.rel), n = e.ev.signals.length, top = e.ev.signals[0]; return html`<tr class="row-link"><td>${accountCell(e.a)}</td><td>${stageBadge(e.a)}</td><td><span class="owner-cell"><span class="avatar tiny">${initials(s(e.a.owner_name))}</span>${e.a.owner_name}</span><small class="sub">Technical: ${e.a.technical_owner_name ?? html`<span class="amber">unassigned</span>`}</small></td><td>${nd ? html`${nd.title}<small class="sub ${s(nd.due_date) < x.today ? "late" : ""}">${fmtLong(s(nd.due_date))}</small>` : html`<span class="muted">No next step</span>`}</td><td>${n ? html`<span class="badge ${top.severity === "warning" ? "amber" : "red"}"><span class="dot"></span>${n} ${n === 1 ? "signal" : "signals"}</span>` : html`<span class="badge green"><span class="dot"></span>On track</span>`}</td></tr>`; })}</tbody></table></div>`
  : html`<div class="empty">${any ? "No accounts match these filters." : "No accounts yet."}</div>`}</section>`;
}
export function newAccountForm(x: Ctx, d: Record<string, string>, errs: Record<string, string> = {}): H {
  const err = (k: string) => errs[k] ? html`<div class="ferr">${errs[k]}</div>` : "";
  return html`<a href="/accounts" class="back">← Accounts</a><div class="page-heading"><h1>Add account</h1></div>
  <form method="post" action="/accounts" style="max-width:720px"><section class="panel"><div class="section-header"><h2>New account</h2></div><div class="card-body">
  <div class="form-grid"><label class="field"><span>Account name *</span><input name="name" value="${d.name ?? ""}" required autofocus>${err("name")}</label><label class="field"><span>Account owner *</span><select name="owner_id">${userOpt(x.users, d.owner_id ?? x.me?.id)}</select>${err("owner_id")}</label></div>
  <label class="field"><span>Customer contact</span><input name="contact" value="${d.contact ?? ""}"></label>
  <label class="field"><span>Problem in one sentence</span><input name="problem" value="${d.problem ?? ""}"></label>
  <label class="checkbox-label"><input type="checkbox" name="existing" value="1" ${d.existing ? "checked" : ""} onchange="document.getElementById('existing').style.display=this.checked?'block':'none'">Existing customer — already signed, skip presales</label>
  <div id="existing" style="display:${d.existing ? "block" : "none"}">
    <label class="field"><span>Agreed scope, in the contract's words *</span><textarea name="ex_deliverables">${d.ex_deliverables ?? ""}</textarea>${err("ex_deliverables")}</label>
    <div class="form-grid"><label class="field"><span>Price / payment terms *</span><input name="ex_price_terms" value="${d.ex_price_terms ?? ""}">${err("ex_price_terms")}</label><label class="field"><span>Contract reference *</span><input name="ex_evidence" value="${d.ex_evidence ?? ""}" placeholder="order form / DocuSign, date">${err("ex_evidence")}</label></div>
    <label class="field"><span>Success metric *</span><input name="ex_success_metric" value="${d.ex_success_metric ?? ""}">${err("ex_success_metric")}</label>
    <div class="form-grid three"><label class="field"><span>Target *</span><input name="ex_success_target" value="${d.ex_success_target ?? ""}"></label><label class="field"><span>Unit</span><input name="ex_success_unit" value="${d.ex_success_unit ?? ""}"></label><label class="field"><span>Direction</span><select name="ex_success_direction"><option value="higher" ${d.ex_success_direction !== "lower" ? "selected" : ""}>higher is better</option><option value="lower" ${d.ex_success_direction === "lower" ? "selected" : ""}>lower is better</option></select></label></div>
    <div class="form-grid"><label class="field"><span>Technical owner *</span><select name="ex_technical_owner_id">${userOpt(x.users.filter((u) => u.role !== "sales"), d.ex_technical_owner_id)}</select>${err("ex_technical_owner_id")}</label><label class="field"><span>Status</span><select name="ex_status"><option value="active" ${d.ex_status !== "delivery" ? "selected" : ""}>Active</option><option value="delivery" ${d.ex_status === "delivery" ? "selected" : ""}>Delivery</option></select></label></div>
    <div class="form-grid three"><label class="field"><span>Started *</span><input type="date" name="ex_started" value="${d.ex_started ?? ""}">${err("ex_started")}</label><label class="field"><span>Renewal date</span><input type="date" name="ex_renewal_date" value="${d.ex_renewal_date ?? ""}">${err("ex_renewal_date")}</label><label class="field"><span>Notice period (days)</span><input name="ex_notice_days" value="${d.ex_notice_days ?? ""}">${err("ex_notice_days")}</label></div></div>
  </div><div class="modal-footer"><a href="/accounts" class="btn">Cancel</a><button class="primary">Save</button></div></section></form>`;
}

// ---------------------------------------------------------------- Account detail
export function accountDetail(a: Row, rel: Related, ev: Evaluation, x: Ctx, tab: string, acts: Row[], panel: string): H {
  const id = s(a.id), t = x.today, v = Number(a.version);
  const open = a.sales_stage !== "lost" && a.delivery_status !== "ended";
  const top = ev.signals[0];
  const bannerCls = top?.severity === "critical" || top?.severity === "high" ? "red" : top ? "amber" : "";
  const steps = [["discovery", "Discovery"], ["proposal", "Proposal"], ["negotiation", "Negotiation"], ["onboarding", "Onboarding"], ["delivery", "Delivery"], ["active", "Active"]];
  const cur = a.sales_stage === "won" ? ({ onboarding_pending: 3, delivery: 4, active: 5, ended: 5 } as Record<string, number>)[s(a.delivery_status)] ?? 3 : ["discovery", "proposal", "negotiation"].indexOf(s(a.sales_stage));
  const stageModal = modal("m-stage", ev.readiness.to && ev.readiness.via !== "end" ? `${stageOf(a)} → ${ev.readiness.toLabel}` : stageOf(a), html`
    ${ev.readiness.to ? html`<div class="readiness"><h3>${ev.readiness.ready ? "Ready to move" : `${ev.readiness.items.filter((i) => !i.ok).length} of ${ev.readiness.items.length} still missing`}</h3><ul class="check">${ev.readiness.items.map((i) => html`<li class="${i.ok ? "ok" : ""}"><span>${i.anchor ? html`<a href="/accounts/${id}?tab=${i.anchor === "approvals" ? "scope" : i.anchor}#${i.anchor}">${i.label}</a>` : i.label}${!i.ok && i.hint ? html`<span class="sub">${i.hint}</span>` : ""}</span></li>`)}</ul></div>
      ${ev.readiness.via === "advance" ? html`<form method="post" action="/accounts/${id}/stage" id="f-advance"><input type="hidden" name="version" value="${v}"><input type="hidden" name="to" value="${ev.readiness.to}"></form>` : ev.readiness.via === "confirm_agreement" ? html`<p class="small">Won is recorded with <a href="/accounts/${id}?tab=scope&open=m-confirm">Confirm agreement</a>, which needs acceptance evidence.</p>` : html`<p class="small">Ending is recorded on <a href="/accounts/${id}?tab=delivery&open=m-end">Delivery &amp; success</a> with a reason.</p>`}` : ""}
    ${isPresales(a) ? html`<details class="drawer"><summary>Move back or mark lost</summary><form method="post" action="/accounts/${id}/stage" class="row" style="margin-bottom:12px"><input type="hidden" name="version" value="${v}"><label class="field"><span>Move back to</span><select name="to">${opt(["discovery", "proposal", "negotiation"].filter((st) => st !== a.sales_stage && ["discovery", "proposal", "negotiation"].indexOf(st) < ["discovery", "proposal", "negotiation"].indexOf(s(a.sales_stage))), undefined, STAGE_LABEL)}</select></label><label class="field" style="flex:2"><span>Reason</span><input name="reason"></label><button>Move back</button></form>
      <form method="post" action="/accounts/${id}/stage" class="row"><input type="hidden" name="version" value="${v}"><input type="hidden" name="to" value="lost"><label class="field"><span>Lost — reason</span><select name="reason">${opt(LOST_REASONS)}</select></label><button>Mark lost</button></form></details>` : ""}`,
    ev.readiness.via === "advance" ? html`<button class="primary" form="f-advance" ${ev.readiness.ready ? "" : "disabled"}>Advance to ${ev.readiness.toLabel}</button>` : html``);
  const bannerBtn = !open ? html`` : ev.readiness.via === "confirm_agreement" ? html`<a class="btn" href="/accounts/${id}?tab=scope&open=m-confirm">Confirm agreement</a>` : a.delivery_status === "onboarding_pending" ? html`<a class="btn" href="/accounts/${id}/handoff">Accept handoff</a>` : ev.readiness.via === "advance" ? openBtn("m-stage", `Advance to ${ev.readiness.toLabel}`) : html``;
  const tabs = ["overview", "scope", "delivery"], tabLabel: Record<string, string> = { overview: "Overview", scope: "Scope & approvals", delivery: "Delivery & success" };
  return html`<a href="/accounts" class="back">← Accounts</a>
  <div class="account-heading"><div class="account-heading-title"><span class="${iconClass(s(a.name))} large">${initials(s(a.name))}</span><div><h1>${a.name}</h1><div class="sub">Owner ${a.owner_name} · Technical owner ${a.technical_owner_name ?? html`<span class="amber">unassigned</span>`}${open ? "" : html` · <span class="red">closed: ${a.lost_reason ?? a.end_reason ?? stageOf(a)}</span>`}</div></div></div>
    <div class="button-group">${a.current_agreement_id ? html`<a href="/accounts/${id}/handoff" class="btn">Handoff</a>` : ""}${open ? html`${openBtn("m-meeting", "Log meeting")}${openBtn("m-action", "Add action", true)}` : ""}</div></div>
  <div class="stage-track">${steps.map(([k, label], i) => html`<button type="button" class="stage-step ${i === cur ? "current" : i < cur ? "past" : ""}" onclick="document.getElementById('m-stage').showModal()"><span>${i < cur ? "✓" : i + 1}</span>${label}</button>`)}${open ? "" : html`<span class="badge neutral" style="margin:10px 14px"><span class="dot"></span>${stageOf(a)}</span>`}</div>
  <div class="account-banner ${bannerCls}"><div><span>${ev.nextStep}</span></div>${bannerBtn}</div>
  <div class="tabs">${tabs.map((tb) => html`<a href="/accounts/${id}?tab=${tb}" class="${tab === tb ? "on" : ""}">${tabLabel[tb]}</a>`)}</div>
  ${tab === "scope" ? scopeTab(a, rel, ev, x) : tab === "delivery" ? deliveryTab(a, rel, ev, x) : overviewTab(a, rel, ev, x, acts)}
  ${stageModal}
  ${modal("m-meeting", "Log meeting", html`<form method="post" action="/accounts/${id}/meetings" id="f-meeting"><div class="form-grid"><label class="field"><span>Date</span><input type="date" name="date" value="${t}"></label></div><label class="field"><span>Summary</span><textarea name="summary" required placeholder="Who, what was said, numbers"></textarea></label>
    <label class="field"><span>Next action (optional)</span><input name="action_title"></label><div class="form-grid"><label class="field"><span>Owner</span><select name="action_owner">${userOpt(x.users, a.owner_id)}</select></label><label class="field"><span>Due</span><input type="date" name="action_due"></label></div><label class="checkbox-label"><input type="checkbox" name="action_customer_side" value="1">Waiting on the customer</label></form>`, html`<button class="primary" form="f-meeting">Save meeting</button>`)}
  ${modal("m-action", "Add action", html`<form method="post" action="/accounts/${id}/tasks" id="f-action"><input type="hidden" name="type" value="action"><label class="field"><span>Action</span><input name="title" required></label><div class="form-grid"><label class="field"><span>Owner</span><select name="owner_id">${userOpt(x.users, a.owner_id)}</select></label><label class="field"><span>Due</span><input type="date" name="due_date"></label></div><label class="checkbox-label"><input type="checkbox" name="committed" value="1">Promised to the customer (needs a date)</label><label class="checkbox-label"><input type="checkbox" name="customer_side" value="1">Waiting on the customer</label></form>`, html`<button class="primary" form="f-action">Add action</button>`)}`;
}

function overviewTab(a: Row, rel: Related, ev: Evaluation, x: Ctx, acts: Row[]): H {
  const id = s(a.id), t = x.today, v = Number(a.version);
  const openTasks = rel.tasks.filter((k) => k.status === "open"), doneTasks = rel.tasks.filter((k) => k.status !== "open");
  const healthBadge = { unknown: html`<span class="badge neutral"><span class="dot"></span>Unknown</span>`, healthy: html`<span class="badge green"><span class="dot"></span>Healthy</span>`, watch: html`<span class="badge amber"><span class="dot"></span>Watch</span>`, at_risk: html`<span class="badge red"><span class="dot"></span>At risk</span>` }[s(a.health)] ?? html`<span class="badge neutral"><span class="dot"></span>Unknown</span>`;
  const taskBtn = (k: Row) => k.type === "review" ? html`<a class="btn" href="/reviews/${k.subject_id}">Decide</a>` : k.type === "handoff" ? html`<a class="btn" href="/accounts/${id}/handoff">Accept</a>` : html`<form method="post" action="/tasks/${k.id}/done"><input type="hidden" name="version" value="${k.version}"><input type="hidden" name="return" value="/accounts/${id}"><button class="task-check" title="Mark done">✓</button></form>`;
  return html`<div class="grid2"><div>
  <section class="panel"><div class="section-header"><h2>Customer</h2><div class="acts">${openBtn("m-owners", "Owners")}${openBtn("m-edit", "Edit details")}</div></div><div class="card-body">
    ${a.problem ? html`<p class="context-problem">${a.problem}</p>` : html`<p class="context-problem amber">No problem statement yet.</p>`}
    <dl class="facts"><div><dt>Customer contact</dt><dd>${a.contact ?? html`<span class="muted">unknown</span>`}</dd></div><div><dt>Buyer</dt><dd>${a.buyer_status === "named" ? a.buyer : a.buyer_status === "unknown" ? html`<span class="amber">explicitly unknown</span>` : html`<span class="muted">not assessed</span>`}</dd></div><div><dt>Budget</dt><dd>${a.budget ?? html`<span class="muted">unknown</span>`}</dd></div><div><dt>Last customer contact</dt><dd>${a.last_customer_contact_at ? html`${fmtLong(s(a.last_customer_contact_at))} <span class="muted">· ${daysBetween(s(a.last_customer_contact_at), t)}d ago</span>` : html`<span class="muted">never</span>`}</dd></div><div><dt>Account owner</dt><dd>${a.owner_name}</dd></div><div><dt>Technical owner</dt><dd>${a.technical_owner_name ?? html`<span class="amber">unassigned</span>`}</dd></div>
    <div><dt>Relationship health</dt><dd>${healthBadge}${a.health_reason ? html` <span class="muted">${a.health_reason}</span>` : ""} <button type="button" class="text" onclick="document.getElementById('m-health').showModal()">Assess</button></dd></div></dl></div></section>
  <section class="panel"><div class="section-header"><h2>Activity <span class="count">${rel.meetings.length}</span></h2>${openBtn("m-meeting", "Log meeting")}</div>
    ${rel.meetings.length ? html`<div class="timeline">${rel.meetings.map((m) => html`<div class="timeline-item"><span class="timeline-dot">●</span><div><small>${fmtLong(s(m.occurred_at))} · Meeting · ${m.author_name ?? ""}</small><p>${m.summary}</p></div></div>`)}</div>` : html`<div class="empty">No meetings logged.</div>`}
    <div class="card-body" style="padding-top:0"><details><summary>History (${acts.length})</summary><div class="timeline" style="padding:0">${acts.map((e) => { const p = parseJSON<Record<string, unknown>>(e.payload, {}); return html`<div class="timeline-item"><span class="timeline-dot">·</span><div><small>${fmtLong(s(e.at).slice(0, 10))} · ${s(e.event_type).replace(/_/g, " ")}${e.actor_name ? html` · ${e.actor_name}` : ""}</small><p class="muted">${Object.entries(p).filter(([, val]) => val != null && val !== "").map(([k, val]) => `${k}: ${Array.isArray(val) ? val.join(", ") : String(val)}`).join(" · ")}</p></div></div>`; })}</div></details></div></section>
  </div><div>
  <section class="panel"><div class="section-header"><h2>Open actions <span class="count">${openTasks.length}</span></h2>${openBtn("m-action", "Add")}</div>
    ${openTasks.length ? openTasks.map((k) => html`<div class="task-row">${taskBtn(k)}<div><div class="task-title">${k.title}${k.committed ? html` <span class="muted">· promised</span>` : ""}</div><small>${k.owner_name ?? "unowned"}${["action", "milestone", "measurement"].includes(s(k.type)) ? html` · <button type="button" class="text" onclick="document.getElementById('m-task-${k.id}').showModal()">Edit</button>` : ""}</small></div><span class="task-date ${k.due_date && s(k.due_date) < t ? "late" : ""}">${k.due_date ? html`${fmtLong(s(k.due_date))} · ${dueWord(s(k.due_date), t)}` : "no date"}</span></div>`) : html`<div class="empty">No open actions.</div>`}
    ${doneTasks.length ? html`<div class="card-body" style="padding-top:12px"><details><summary>${doneTasks.length} completed</summary><ul class="small muted" style="margin:8px 0 0;padding-left:18px">${doneTasks.map((k) => html`<li>${fmtLong(s(k.done_at).slice(0, 10))} ${k.title}</li>`)}</ul></details></div>` : ""}</section>
  <section class="panel"><div class="section-header"><h2>Risk signals <span class="count">${ev.signals.length}</span></h2></div>
    ${ev.signals.length ? ev.signals.map((g) => html`<div class="risk-item"><div><span class="badge ${g.severity === "warning" ? "amber" : "red"}"><span class="dot"></span>${SEVERITY_LABEL[g.severity]}</span><p style="margin-top:8px">${g.reason}</p>${g.detail ? html`<p class="muted">${g.detail}</p>` : ""}<small>${nameOf(x, g.ownerId)}</small></div>${actionFor(g, a)}</div>`) : html`<div class="empty">No open signals.</div>`}</section>
  </div></div>
  ${modal("m-edit", "Edit customer details", html`<form method="post" action="/accounts/${id}/edit/overview" id="f-edit"><input type="hidden" name="version" value="${v}"><label class="field"><span>Problem, in the customer's words</span><textarea name="problem">${a.problem ?? ""}</textarea></label><div class="form-grid"><label class="field"><span>Contact</span><input name="contact" value="${a.contact ?? ""}"></label><label class="field"><span>Budget</span><input name="budget" value="${a.budget ?? ""}"></label><label class="field"><span>Buyer status</span><select name="buyer_status">${opt(["not_assessed", "unknown", "named"], s(a.buyer_status), { not_assessed: "not assessed", unknown: "explicitly unknown", named: "named" })}</select></label><label class="field"><span>Buyer</span><input name="buyer" value="${a.buyer ?? ""}"></label></div></form>`, html`<button class="primary" form="f-edit">Save</button>`)}
  ${modal("m-owners", "Owners", html`<form method="post" action="/accounts/${id}/edit/owners" id="f-owners"><input type="hidden" name="version" value="${v}"><div class="form-grid"><label class="field"><span>Account owner</span><select name="owner_id">${userOpt(x.users, a.owner_id)}</select></label><label class="field"><span>Technical owner</span><select name="technical_owner_id">${userOpt(x.users, a.technical_owner_id, "unassigned")}</select></label></div></form>`, html`<button class="primary" form="f-owners">Save</button>`)}
  ${modal("m-health", "Relationship health", html`<form method="post" action="/accounts/${id}/edit/health" id="f-health"><input type="hidden" name="version" value="${v}"><div class="form-grid"><label class="field"><span>Health</span><select name="health">${opt(["unknown", "healthy", "watch", "at_risk"], s(a.health), { unknown: "Unknown", healthy: "Healthy", watch: "Watch", at_risk: "At risk" })}</select></label></div><label class="field"><span>Reason</span><input name="health_reason" value="${a.health_reason ?? ""}"></label></form>`, html`<button class="primary" form="f-health">Save</button>`)}
  ${openTasks.filter((k) => ["action", "milestone", "measurement"].includes(s(k.type))).map((k) => modal(`m-task-${k.id}`, "Edit action", html`<form method="post" action="/tasks/${k.id}/edit" id="f-task-${k.id}"><input type="hidden" name="version" value="${k.version}"><label class="field"><span>Title</span><input name="title" value="${k.title}"></label><div class="form-grid"><label class="field"><span>Owner</span><select name="owner_id">${userOpt(x.users, k.owner_id)}</select></label><label class="field"><span>Due</span><input type="date" name="due_date" value="${k.due_date ?? ""}"></label></div><label class="checkbox-label"><input type="checkbox" name="committed" value="1" ${k.committed ? "checked" : ""}>Promised to the customer</label>${k.type === "milestone" ? html`<label class="checkbox-label"><input type="checkbox" name="required" value="1" ${k.required ? "checked" : ""}>Required before Active</label>` : ""}</form>`, html`<button class="primary" form="f-task-${k.id}">Save</button>`))}`;
}

function scopeTab(a: Row, rel: Related, ev: Evaluation, x: Ctx): H {
  const id = s(a.id), t = x.today, v = Number(a.version);
  const p = latest(rel.proposals), req = latest(rel.requirements);
  const h = handlingOf(p);
  const agreement = rel.agreements.find((g) => g.id === a.current_agreement_id) ?? null;
  const agP = agreement ? rel.proposals.find((q) => q.id === agreement.proposal_id) : null;
  const states = reviewStates(a, rel);
  const stateTone: Record<string, string> = { satisfied: "green", open: "amber", missing: "amber", conditional: "amber", stale: "red", blocked: "red" };
  const stateWord: Record<string, string> = { satisfied: "Approved", conditional: "Conditional", blocked: "Blocked", open: "Open", missing: "Missing", stale: "Stale" };
  const propBlock = (pp: Row) => html`<dl class="facts single"><div><dt>Deliverables</dt><dd><pre class="wrap">${pp.deliverables ?? "—"}</pre></dd></div><div><dt>Exclusions</dt><dd>${pp.exclusions ?? "—"}</dd></div><div><dt>Price / payment</dt><dd>${pp.price_terms ?? "—"}</dd></div><div><dt>Dates</dt><dd>${pp.dates ?? "—"}</dd></div><div><dt>Customer responsibilities</dt><dd>${pp.customer_responsibilities ?? "—"}</dd></div>
    <div><dt>Success criterion</dt><dd>${pp.success_metric ?? "—"} ${pp.success_target != null ? html`→ ${pp.success_target}${pp.success_unit ?? ""} <span class="muted">(${pp.success_direction} is better; basis: ${pp.success_basis ?? "unspecified"})</span>` : html`<span class="amber">no target</span>`}</dd></div>
    <div><dt>Proposed data handling</dt><dd>${handlingText(handlingOf(pp))}</dd></div></dl>`;
  const canConfirm = a.sales_stage === "negotiation" || (agreement && p && p.id !== agP?.id);
  return html`<div class="grid2"><div>
  <section class="panel" id="proposal"><div class="section-header"><h2>Proposed scope &amp; terms ${p ? html`<span class="badge neutral">rev ${p.revision}${p.shared_at ? ` · shared ${fmtLong(s(p.shared_at))}` : " · not shared"}</span>` : ""}</h2>${openBtn("m-proposal", p ? "Edit" : "Draft proposal")}</div><div class="card-body">
    ${p ? propBlock(p) : html`<p class="muted">No proposal yet.</p>`}
    ${p?.change_note ? html`<p class="muted" style="margin-top:14px">Change note: ${p.change_note}</p>` : ""}
    ${agP && p && agP.id !== p.id ? html`<p class="amber" style="margin-top:14px">This revision is a proposed change. The accepted agreement (rev ${agP.revision}) stays in force until an amendment is accepted.</p>` : ""}
    ${rel.proposals.length > 1 ? html`<details style="margin-top:16px"><summary>Earlier revisions (${rel.proposals.length - 1})</summary>${rel.proposals.slice(1).map((pp) => html`<h3 style="margin:16px 0 8px">Rev ${pp.revision} · ${fmtLong(s(pp.created_at).slice(0, 10))}${pp.change_note ? ` · ${pp.change_note}` : ""}</h3>${propBlock(pp)}`)}</details>` : ""}</div></section>
  <section class="panel" id="confirm"><div class="section-header"><h2>Accepted agreement ${agP ? html`<span class="badge green">rev ${agP.revision}</span>` : ""}</h2><div class="acts">${agreement ? html`<a class="btn" href="/accounts/${id}/handoff">Handoff</a>` : ""}${canConfirm ? openBtn("m-confirm", agreement ? "Accept amendment" : "Confirm agreement", true) : ""}</div></div><div class="card-body">
    ${agreement && agP ? html`<p>Accepted ${fmtLong(s(agreement.accepted_at))} by ${agreement.accepted_by_name}. Evidence: <i>${agreement.acceptance_evidence}</i>${agreement.supersedes_id ? " · supersedes an earlier agreement" : ""}</p>
      <details style="margin-top:12px"><summary>Agreement contents</summary><div style="margin-top:12px">${propBlock(agP)}</div></details>` : html`<p class="muted">None yet. ${a.sales_stage === "negotiation" ? "Confirm the agreement when the customer has accepted a shared revision." : ""}</p>`}</div></section>
  <section class="panel" id="approvals"><div class="section-header"><h2>Stage readiness</h2></div><div class="card-body"><ul class="check">${ev.readiness.items.map((i) => html`<li class="${i.ok ? "ok" : ""}"><span>${i.label}${!i.ok && i.hint ? html`<span class="sub">${i.hint}</span>` : ""}</span></li>`)}</ul></div></section>
  </div><div>
  <section class="panel" id="requirements"><div class="section-header"><h2>Customer data restrictions ${req ? html`<span class="badge neutral">rev ${req.revision}</span>` : ""}</h2>${openBtn("m-req", req ? "Update" : "Record")}</div><div class="card-body">
    ${ev.conflicts.length ? html`<div class="error"><b>Proposed change requires review.</b> ${ev.conflicts.join("; ")}.</div>` : ""}
    ${ev.agreementConflicts.length ? html`<div class="error"><b>Current agreement needs review.</b> ${ev.agreementConflicts.join("; ")}.</div>` : ""}
    ${req ? html`<p style="margin-bottom:12px"><span class="badge ${req.restriction_status === "specified" ? "amber" : req.restriction_status === "none_stated" ? "green" : "neutral"}"><span class="dot"></span>${{ unknown: "Unknown", none_stated: "None stated", specified: "Specified" }[s(req.restriction_status)]}</span></p>
      ${req.restriction_status === "specified" ? html`<blockquote>${req.wording}</blockquote><dl class="facts"><div><dt>Covered activities</dt><dd>${parseJSON<string[]>(req.activities, []).join(", ") || "—"}</dd></div><div><dt>External processing allowed</dt><dd>${req.external_processing}</dd></div><div><dt>Retention</dt><dd>${req.retention}${req.retention_note ? ` — ${req.retention_note}` : ""}</dd></div><div><dt>Training use allowed</dt><dd>${req.training_use}</dd></div><div><dt>Evidence</dt><dd>${req.evidence_note ?? "—"}</dd></div></dl>` : req.evidence_note ? html`<p class="muted">${req.evidence_note}</p>` : ""}` : html`<p class="amber">Not recorded.</p>`}</div></section>
  <section class="panel" id="reviews"><div class="section-header"><h2>Technical reviews <span class="count">${states.length}</span></h2>${openBtn("m-review", "Request")}</div>
    ${states.length ? states.map((st) => html`<div class="risk-item"><div><span class="badge ${stateTone[st.state]}"><span class="dot"></span>${stateWord[st.state] ?? st.state}</span><p style="margin-top:8px">${st.why}</p></div>${st.review ? html`<a class="btn" href="/reviews/${st.review.id}">Open</a>` : ""}</div>`) : html`<div class="empty">No review is required yet.</div>`}
    ${rel.reviews.filter((r) => !states.some((st) => st.review?.id === r.id)).length ? html`<div class="card-body" style="padding-top:12px"><details><summary>Other reviews</summary><ul class="small muted" style="margin:8px 0 0;padding-left:18px">${rel.reviews.filter((r) => !states.some((st) => st.review?.id === r.id)).map((r) => html`<li>${REVIEW_KINDS[s(r.kind)]} — ${r.status} · ${r.reviewer_name ?? "no reviewer"} · <a href="/reviews/${r.id}">open</a></li>`)}</ul></details></div>` : ""}</section>
  <section class="panel" id="calibration"><div class="card-body">${calibrationBlock(a, rel, x)}</div></section>
  </div></div>
  ${modal("m-proposal", p ? `Edit proposal (creates revision ${Number(p.revision) + 1})` : "Draft proposal", html`<form method="post" action="/accounts/${id}/proposals" id="f-proposal">
    <label class="field"><span>Deliverables *</span><textarea name="deliverables">${p?.deliverables ?? ""}</textarea></label>
    <div class="form-grid"><label class="field"><span>Exclusions</span><input name="exclusions" value="${p?.exclusions ?? ""}"></label><label class="field"><span>Price / payment terms</span><input name="price_terms" value="${p?.price_terms ?? ""}"></label><label class="field"><span>Dates</span><input name="dates" value="${p?.dates ?? ""}"></label><label class="field"><span>Customer responsibilities</span><input name="customer_responsibilities" value="${p?.customer_responsibilities ?? ""}"></label></div>
    <h3 style="margin:6px 0 12px">Success criterion</h3>
    <label class="field"><span>Metric *</span><input name="success_metric" value="${p?.success_metric ?? ""}"></label>
    <div class="form-grid three"><label class="field"><span>Target</span><input name="success_target" value="${p?.success_target ?? ""}"></label><label class="field"><span>Unit</span><input name="success_unit" value="${p?.success_unit ?? ""}"></label><label class="field"><span>Direction</span><select name="success_direction">${opt(["higher", "lower"], s(p?.success_direction) || "higher", { higher: "higher is better", lower: "lower is better" })}</select></label></div>
    <label class="field"><span>Evaluation basis</span><input name="success_basis" value="${p?.success_basis ?? ""}" placeholder="dataset / version / method"></label>
    <h3 style="margin:6px 0 12px">Proposed data handling</h3>
    <label class="field"><span>Activities</span><div class="row">${ACTIVITIES.map((ac) => html`<label class="checkbox-label" style="margin:0"><input type="checkbox" name="h_activities[]" value="${ac}" ${(h.activities ?? []).includes(ac) ? "checked" : ""}>${ac}</label>`)}</div></label>
    <div class="form-grid"><label class="field"><span>External processing</span><select name="h_external">${opt(["", "no", "yes"], h.external_processing ?? "", { "": "undeclared", no: "no", yes: "yes" })}</select></label><label class="field"><span>External processors (comma-separated)</span><input name="h_processors" value="${(h.external_processors ?? []).join(", ")}"></label><label class="field"><span>Retention</span><select name="h_retention">${opt(["", "none", "custom"], h.retention ?? "", { "": "undeclared", none: "none", custom: "custom" })}</select></label><label class="field"><span>Retention note</span><input name="h_retention_note" value="${h.retention_note ?? ""}"></label><label class="field"><span>Training use</span><select name="h_training">${opt(["", "no", "yes"], h.training_use ?? "", { "": "undeclared", no: "no", yes: "yes" })}</select></label></div>
    <h3 style="margin:6px 0 12px">This revision</h3>
    <label class="field"><span>Change note</span><input name="change_note" placeholder="why this revision"></label>
    <div class="form-grid"><label class="checkbox-label" style="margin:0"><input type="checkbox" name="shared" value="1">Shared with the customer on</label><input type="date" name="shared_at" value="${t}"></div>
    <label class="field" style="margin-top:14px"><span>Waive technical validation — reason (only when no unresolved data restriction)</span><input name="validation_waived_reason" value="${p?.validation_waived_reason ?? ""}"></label></form>`,
    html`<button class="primary" form="f-proposal">Save as revision ${p ? Number(p.revision) + 1 : 1}</button>`)}
  ${canConfirm ? modal("m-confirm", agreement ? `Accept amendment (rev ${p?.revision})` : `Confirm agreement (rev ${p?.revision})`, html`<form method="post" action="/accounts/${id}/agreements" id="f-confirm"><input type="hidden" name="version" value="${v}"><label class="field"><span>Acceptance evidence — note or document link *</span><input name="evidence" required placeholder="order form link, signed PDF name, email subject"></label><div class="form-grid"><label class="field"><span>Accepted on</span><input type="date" name="accepted_at" value="${t}"></label></div><p class="muted">${agreement ? "Keeps the earlier agreement and reopens handoff acceptance." : "Marks the deal Won, freezes this revision and creates the handoff."}</p></form>`, html`<button class="primary" form="f-confirm">${agreement ? "Accept amendment" : "Confirm agreement"}</button>`) : ""}
  ${modal("m-req", req ? `Update data restrictions (revision ${Number(req.revision) + 1})` : "Record data restrictions", html`<form method="post" action="/accounts/${id}/requirements" id="f-req">
    <label class="field"><span>Data restrictions</span><select name="restriction_status" onchange="document.getElementById('reqx').style.display=this.value==='specified'?'block':'none'">${opt(["unknown", "none_stated", "specified"], s(req?.restriction_status) || "unknown", { unknown: "unknown", none_stated: "none stated", specified: "specified" })}</select></label>
    <div id="reqx" style="display:${req?.restriction_status === "specified" ? "block" : "none"}">
      <label class="field"><span>Exact customer wording *</span><textarea name="wording">${req?.wording ?? ""}</textarea></label>
      <label class="field"><span>Covered activities</span><div class="row">${ACTIVITIES.map((ac) => html`<label class="checkbox-label" style="margin:0"><input type="checkbox" name="activities[]" value="${ac}" ${parseJSON<string[]>(req?.activities, []).includes(ac) ? "checked" : ""}>${ac}</label>`)}</div></label>
      <div class="form-grid"><label class="field"><span>External processing allowed</span><select name="external_processing">${opt(["unknown", "yes", "no"], s(req?.external_processing) || "unknown")}</select></label><label class="field"><span>Training use allowed</span><select name="training_use">${opt(["unknown", "yes", "no"], s(req?.training_use) || "unknown")}</select></label><label class="field"><span>Retention requirement</span><select name="retention">${opt(["unknown", "none", "custom"], s(req?.retention) || "unknown")}</select></label><label class="field"><span>Retention note</span><input name="retention_note" value="${req?.retention_note ?? ""}"></label></div></div>
    <label class="field"><span>Evidence / clarification note</span><input name="evidence_note" value="${req?.evidence_note ?? ""}"></label></form>`, html`<button class="primary" form="f-req">Save</button>`)}
  ${modal("m-review", "Request a review", html`<form method="post" action="/accounts/${id}/reviews" id="f-review"><div class="form-grid"><label class="field"><span>Kind</span><select name="kind">${opt(Object.keys(REVIEW_KINDS), "technical_validation", REVIEW_KINDS)}</select></label><label class="field"><span>Reviewer</span><select name="reviewer_id">${userOpt(x.users, a.technical_owner_id, "technical owner / unassigned")}</select></label></div><label class="field"><span>Question</span><input name="question"></label></form>`, html`<button class="primary" form="f-review">Request</button>`)}`;
}
function handlingText(h: ReturnType<typeof handlingOf>): H {
  if (!h.external_processing && !h.retention && !(h.external_processors ?? []).length) return html`<span class="amber">undeclared</span>`;
  return html`activities: ${(h.activities ?? []).join(", ") || "—"}; external processing: ${h.external_processing ?? "undeclared"}${(h.external_processors ?? []).length ? ` (${h.external_processors!.join(", ")})` : ""}; retention: ${h.retention ?? "undeclared"}${h.retention_note ? ` — ${h.retention_note}` : ""}; training use: ${h.training_use ?? "undeclared"}`;
}

function deliveryTab(a: Row, rel: Related, ev: Evaluation, x: Ctx): H {
  const id = s(a.id), t = x.today, v = Number(a.version);
  if (!a.current_agreement_id) return html`<section class="panel"><div class="empty">Nothing here until an agreement is confirmed.</div></section>`;
  const h = rel.handoffs.find((k) => k.agreement_id === a.current_agreement_id);
  const ms = rel.tasks.filter((k) => k.type === "milestone"), o = rel.outcome, os = outcomeStatus(o);
  const osTone: Record<string, string> = { met: "green", below: "red", not_comparable: "amber", not_measured: "amber", none: "neutral" };
  const checkin = rel.tasks.filter((k) => k.status === "open" && k.due_date && /review|check-?in|briefing|QBR/i.test(s(k.title))).sort((p, q) => s(p.due_date).localeCompare(s(q.due_date)))[0];
  const ownerSel = (name: string) => html`<label class="field"><span>Owner</span><select name="${name}">${userOpt(x.users, a.technical_owner_id ?? a.owner_id)}</select></label>`;
  return html`<div class="grid2"><div>
  <section class="panel"><div class="section-header"><h2>Handoff</h2><a class="btn" href="/accounts/${id}/handoff">Open handoff</a></div><div class="card-body">
    ${h ? (h.accepted_at ? html`<span class="badge green"><span class="dot"></span>Accepted</span> <span class="muted">${fmtLong(s(h.accepted_at))} by ${h.accepted_by_name}</span>${h.stale_reason ? html`<p class="amber" style="margin-top:10px">Acceptance reopened: ${h.stale_reason}</p>` : ""}` : html`<span class="badge red"><span class="dot"></span>Awaiting acceptance</span> <span class="muted">by ${a.technical_owner_name ?? html`<span class="amber">unassigned technical owner</span>`}</span>${h.stale_reason ? html`<p class="muted" style="margin-top:10px">${h.stale_reason}</p>` : ""}`) : html`<span class="muted">No handoff packet (backfilled engagement).</span>`}</div></section>
  <section class="panel"><div class="section-header"><h2>Milestones <span class="count">${ms.length}</span></h2>${openBtn("m-milestone", "Add")}</div>
    ${ms.length ? ms.map((k) => html`<div class="task-row ${k.status !== "open" ? "muted" : ""}">${k.status === "open" ? html`<form method="post" action="/tasks/${k.id}/done"><input type="hidden" name="version" value="${k.version}"><input type="hidden" name="return" value="/accounts/${id}?tab=delivery"><button class="task-check" title="Mark done">✓</button></form>` : html`<span class="task-check" style="color:#49734b;background:#eff5e8;display:inline-flex;align-items:center;justify-content:center">✓</span>`}<div><div class="task-title">${k.title}${k.committed ? html` <span class="muted">· promised</span>` : ""}</div><small>${k.owner_name ?? "unassigned"}${k.required ? " · required before Active" : ""}</small></div><span class="task-date ${k.status === "open" && k.due_date && s(k.due_date) < t ? "late" : ""}">${fmtLong(s(k.due_date))}${k.status === "open" && k.due_date ? html` · ${dueWord(s(k.due_date), t)}` : ""}</span></div>`) : html`<div class="empty">No milestones yet.</div>`}</section>
  <section class="panel" id="blockers"><div class="section-header"><h2>Blockers <span class="count">${rel.blockers.filter((b) => !b.resolved_at).length}</span></h2>${openBtn("m-blocker", "Add")}</div>
    ${rel.blockers.length ? rel.blockers.map((b) => html`<div class="risk-item ${b.resolved_at ? "muted" : ""}"><div>${b.resolved_at ? html`<span class="badge neutral"><span class="dot"></span>Resolved ${fmtLong(s(b.resolved_at))}</span>` : html`<span class="badge red"><span class="dot"></span>Open ${daysBetween(s(b.opened_at), t)}d</span>`}<p style="margin-top:8px">${b.description}</p><small>${b.owner_name ?? ""}${b.resolution ? ` · ${b.resolution}` : ""}</small></div>${b.resolved_at ? "" : openBtn(`m-resolve-${b.id}`, "Resolve")}</div>`) : html`<div class="empty">No blockers.</div>`}</section>
  </div><div>
  <section class="panel" id="outcome"><div class="section-header"><h2>Measured success</h2><div class="acts">${openBtn("m-measure-task", "Add measurement task")}${openBtn("m-outcome", o ? "Record result" : "Set metric", true)}</div></div><div class="card-body">
    ${o ? html`<p style="margin-bottom:12px"><b>${o.metric}</b></p><p style="margin-bottom:16px"><span class="badge ${osTone[os.status]}"><span class="dot"></span>${outcomeShort(o)}</span></p>
      <dl class="facts"><div><dt>Baseline</dt><dd>${o.baseline != null ? html`${o.baseline}${o.unit ?? ""}${o.baseline_basis ? html` <span class="muted">on ${o.baseline_basis}</span>` : ""}` : html`<span class="muted">unknown</span>`}</dd></div><div><dt>Target</dt><dd>${o.target != null ? html`${o.target}${o.unit ?? ""} <span class="muted">(${o.direction} is better)</span>` : html`<span class="muted">unknown</span>`}</dd></div><div><dt>Latest</dt><dd>${o.latest != null ? html`${o.latest}${o.unit ?? ""} <span class="muted">on ${o.latest_basis ?? "?"}, ${fmtLong(s(o.measured_at))}</span>` : html`<span class="muted">not measured</span>`}</dd></div></dl>
      ${(rel.measurements ?? []).length ? html`<details style="margin-top:14px"><summary>Measurement history (${(rel.measurements ?? []).length})</summary><table style="margin-top:8px"><thead><tr><th style="padding-left:0">Measured</th><th>Value</th><th>Basis</th><th>By</th></tr></thead><tbody>${(rel.measurements ?? []).map((m) => html`<tr><td class="nowrap" style="padding-left:0">${fmtLong(s(m.measured_at))}</td><td>${m.value}${o?.unit ?? ""}</td><td>${m.basis ?? "—"}${o?.baseline_basis && m.basis !== o.baseline_basis ? html` <span class="amber">(differs from baseline basis)</span>` : ""}</td><td>${m.recorded_by_name ?? "—"}</td></tr>`)}</tbody></table></details>` : ""}` : html`<p class="muted">No success metric recorded.</p>`}</div></section>
  <section class="panel"><div class="section-header"><h2>Check-ins, renewal, expansion</h2><div class="acts">${openBtn("m-renewal", "Edit")}${a.delivery_status !== "ended" ? openBtn("m-end", "End engagement") : ""}</div></div><div class="card-body">
    <dl class="facts"><div><dt>Next check-in</dt><dd>${checkin ? html`${fmtLong(s(checkin.due_date))} — ${checkin.title}` : html`<span class="amber">none scheduled</span>`}</dd></div><div><dt>Renewal</dt><dd>${a.renewal_date ? html`${fmtLong(s(a.renewal_date))} <span class="muted">(${dueWord(s(a.renewal_date), t)})</span>${a.renewal_notice_days ? html`<div class="sub">Notice due ${fmtLong(addDays(s(a.renewal_date), -Number(a.renewal_notice_days)))} (${a.renewal_notice_days} days before)</div>` : ""}` : html`<span class="muted">no date</span>`}</dd></div><div><dt>Expansion</dt><dd>${a.expansion_note ?? html`<span class="muted">none noted</span>`}</dd></div></dl></div></section>
  </div></div>
  ${modal("m-milestone", "Add milestone", html`<form method="post" action="/accounts/${id}/tasks" id="f-milestone"><input type="hidden" name="type" value="milestone"><label class="field"><span>Milestone</span><input name="title" required></label><div class="form-grid">${ownerSel("owner_id")}<label class="field"><span>Due *</span><input type="date" name="due_date" required></label></div><label class="checkbox-label"><input type="checkbox" name="required" value="1" checked>Required before Active</label></form>`, html`<button class="primary" form="f-milestone">Add</button>`)}
  ${modal("m-blocker", "Add blocker", html`<form method="post" action="/accounts/${id}/blockers" id="f-blocker"><label class="field"><span>Blocker</span><input name="description" required></label><div class="form-grid">${ownerSel("owner_id")}</div></form>`, html`<button class="primary" form="f-blocker">Add</button>`)}
  ${rel.blockers.filter((b) => !b.resolved_at).map((b) => modal(`m-resolve-${b.id}`, "Resolve blocker", html`<form method="post" action="/blockers/${b.id}/resolve" id="f-resolve-${b.id}"><p style="margin-bottom:14px">${b.description}</p><label class="field"><span>How it was resolved</span><input name="resolution"></label></form>`, html`<button class="primary" form="f-resolve-${b.id}">Resolve</button>`))}
  ${modal("m-outcome", o ? "Record result" : "Set success metric", html`<form method="post" action="/accounts/${id}/outcome" id="f-outcome"><input type="hidden" name="version" value="${o?.version ?? ""}">
    <div class="form-grid"><label class="field"><span>Metric</span><input name="metric" value="${o?.metric ?? ""}"></label><label class="field"><span>Unit</span><input name="unit" value="${o?.unit ?? ""}"></label><label class="field"><span>Direction</span><select name="direction">${opt(["higher", "lower"], s(o?.direction) || "higher", { higher: "higher is better", lower: "lower is better" })}</select></label><label class="field"><span>Target</span><input name="target" value="${o?.target ?? ""}"></label></div>
    <div class="form-grid"><label class="field"><span>Baseline (blank = unknown)</span><input name="baseline" value="${o?.baseline ?? ""}"></label><label class="field"><span>Baseline basis</span><input name="baseline_basis" value="${o?.baseline_basis ?? ""}"></label></div>
    <div class="form-grid three"><label class="field"><span>Latest (blank = not measured)</span><input name="latest" value="${o?.latest ?? ""}"></label><label class="field"><span>Latest basis</span><input name="latest_basis" value="${o?.latest_basis ?? o?.baseline_basis ?? ""}"></label><label class="field"><span>Measured on</span><input type="date" name="measured_at" value="${s(o?.measured_at) || t}"></label></div>
    <label class="field"><span>If not measured: reason</span><input name="not_measured_reason" value="${o?.not_measured_reason ?? ""}"></label></form>`, html`<button class="primary" form="f-outcome">Save</button>`)}
  ${modal("m-measure-task", "Add measurement task", html`<form method="post" action="/accounts/${id}/tasks" id="f-measure"><input type="hidden" name="type" value="measurement"><input type="hidden" name="committed" value="1"><label class="field"><span>Task</span><input name="title" value="Measure ${o?.metric ?? "success metric"}"></label><div class="form-grid">${ownerSel("owner_id")}<label class="field"><span>Due *</span><input type="date" name="due_date" required></label></div></form>`, html`<button class="primary" form="f-measure">Add</button>`)}
  ${modal("m-renewal", "Renewal and expansion", html`<form method="post" action="/accounts/${id}/edit/renewal" id="f-renewal"><input type="hidden" name="version" value="${v}"><div class="form-grid"><label class="field"><span>Renewal date</span><input type="date" name="renewal_date" value="${a.renewal_date ?? ""}"></label><label class="field"><span>Notice period (days before)</span><input name="renewal_notice_days" value="${a.renewal_notice_days ?? ""}"></label></div><label class="field"><span>Expansion next step</span><input name="expansion_note" value="${a.expansion_note ?? ""}"></label></form>`, html`<button class="primary" form="f-renewal">Save</button>`)}
  ${a.delivery_status !== "ended" ? modal("m-end", "End engagement", html`<form method="post" action="/accounts/${id}/end" id="f-end"><label class="field"><span>Outcome / reason *</span><input name="reason" required></label><div class="form-grid"><label class="field"><span>End date</span><input type="date" name="ended_at" value="${t}"></label></div></form>`, html`<button class="primary" form="f-end">End engagement</button>`) : ""}`;
}

// ---------------------------------------------------------------- Review decision panel
export function reviewPanel(rv: Row, a: Row, rel: Related, ev: Evaluation, x: Ctx): H {
  const hist = parseJSON<Row[]>(rv.history, []);
  const p = rel.proposals.find((q) => q.id === rv.proposal_id) ?? latest(rel.proposals), req = rel.requirements.find((q) => q.id === rv.requirements_id) ?? latest(rel.requirements);
  const prior = rel.reviews.filter((r) => r.kind === rv.kind && r.id !== rv.id && r.decided_at).sort((m, k) => s(k.decided_at).localeCompare(s(m.decided_at)))[0];
  const priorP = prior ? rel.proposals.find((q) => q.id === prior.proposal_id) : null;
  const FIELD: Record<string, string> = { deliverables: "Deliverables", exclusions: "Exclusions", price_terms: "Price / payment", success_metric: "Success metric", success_target: "Target", success_basis: "Evaluation basis" };
  const diff = priorP && p ? Object.keys(FIELD).filter((k) => s(priorP[k]) !== s(p[k])) : [];
  const hDiff = priorP && p && JSON.stringify(handlingOf(priorP)) !== JSON.stringify(handlingOf(p));
  const conds = parseJSON<{ text: string; done: boolean }[]>(rv.conditions, []);
  const tone: Record<string, string> = { open: "amber", approved: "green", conditional: "amber", blocked: "red" };
  return html`<a href="/accounts/${a.id}?tab=scope" class="back">← ${a.name}</a>
  <div class="account-heading"><div><h1>${REVIEW_KINDS[s(rv.kind)]}</h1><div class="sub"><span class="badge ${tone[s(rv.status)] ?? "neutral"}"><span class="dot"></span>${rv.status}</span> Reviewer ${rv.reviewer_name ?? html`<span class="amber">unassigned</span>`} · requested ${fmtLong(s(rv.requested_at))}${rv.reopened_reason ? html` · <span class="red">reopened: ${rv.reopened_reason}</span>` : ""}</div></div></div>
  <div class="grid2"><div>
  <section class="panel"><div class="section-header"><h2>Proposal under review ${p ? html`<span class="badge neutral">rev ${p.revision}</span>` : ""}</h2></div><div class="card-body">
    ${rv.question ? html`<p class="context-problem">${rv.question}</p>` : ""}
    ${p ? html`<dl class="facts single"><div><dt>Deliverables</dt><dd><pre class="wrap">${p.deliverables}</pre></dd></div><div><dt>Terms</dt><dd>${p.price_terms ?? "—"}</dd></div><div><dt>Success</dt><dd>${p.success_metric} → ${p.success_target}${p.success_unit ?? ""} <span class="muted">on ${p.success_basis ?? "?"}</span></dd></div><div><dt>Data handling</dt><dd>${handlingText(handlingOf(p))}</dd></div></dl>` : html`<p class="muted">No proposal.</p>`}
    ${prior ? html`<h3 style="margin:18px 0 8px">Since the prior decision <span class="muted">(rev ${priorP?.revision}, ${prior.status} ${fmtLong(s(prior.decided_at))})</span></h3>${diff.length || hDiff ? html`<dl class="facts single">${diff.map((k) => html`<div><dt>${FIELD[k]}</dt><dd><span class="muted">was:</span> ${s(priorP![k]) || "—"}<br><span class="muted">now:</span> ${s(p![k]) || "—"}</dd></div>`)}${hDiff ? html`<div><dt>Data handling</dt><dd><span class="muted">was:</span> ${handlingText(handlingOf(priorP))}<br><span class="muted">now:</span> ${handlingText(handlingOf(p))}</dd></div>` : ""}</dl>` : html`<p class="muted">No material change in the proposal; the requirements or a re-request triggered this.</p>`}` : ""}</div></section>
  <section class="panel"><div class="section-header"><h2>Customer data restrictions ${req ? html`<span class="badge neutral">rev ${req.revision}</span>` : ""}</h2></div><div class="card-body">
    ${ev.conflicts.length ? html`<div class="error">Explicit mismatch: ${ev.conflicts.join("; ")}</div>` : ""}
    ${req ? html`<p style="margin-bottom:10px"><span class="badge ${req.restriction_status === "specified" ? "amber" : req.restriction_status === "none_stated" ? "green" : "neutral"}"><span class="dot"></span>${{ unknown: "Unknown", none_stated: "None stated", specified: "Specified" }[s(req.restriction_status)]}</span></p>${req.wording ? html`<blockquote>${req.wording}</blockquote>` : ""}${req.restriction_status === "specified" ? html`<dl class="facts"><div><dt>External processing allowed</dt><dd>${req.external_processing}</dd></div><div><dt>Retention</dt><dd>${req.retention}${req.retention_note ? ` — ${req.retention_note}` : ""}</dd></div><div><dt>Training use allowed</dt><dd>${req.training_use}</dd></div></dl>` : ""}` : html`<p class="amber">Not recorded.</p>`}</div></section>
  ${hist.length ? html`<section class="panel"><div class="section-header"><h2>Earlier decisions <span class="count">${hist.length}</span></h2></div>${hist.map((h) => html`<div class="risk-item"><div><span class="badge ${tone[s(h.status)] ?? "neutral"}"><span class="dot"></span>${h.status}</span> <span class="muted">${fmtLong(s(h.decided_at))} · ${rel.users.find((u) => u.id === h.reviewer_id)?.name ?? "—"} · proposal rev ${rel.proposals.find((pp) => pp.id === h.proposal_id)?.revision ?? "?"}</span><p style="margin-top:8px">${h.decision_note ?? ""}</p>${parseJSON<{ text: string; done: boolean }[]>(h.conditions, []).length ? html`<small>Conditions: ${parseJSON<{ text: string; done: boolean }[]>(h.conditions, []).map((cd) => (cd.done ? "✓ " : "○ ") + cd.text).join("; ")}</small>` : ""}<small>Reopened for: ${h.reopened_for}</small></div></div>`)}</section>` : ""}
  </div><div>
  <section class="panel"><div class="section-header"><h2>Decision</h2></div><div class="card-body">
  ${rv.status === "open" ? html`<form method="post" action="/reviews/${rv.id}/decide"><input type="hidden" name="version" value="${rv.version}">
    <label class="field"><span>Outcome</span><select name="status"><option value="">—</option>${opt(["approved", "conditional", "blocked"], undefined, { approved: "Approved", conditional: "Approved with conditions", blocked: "Blocked" })}</select></label>
    <label class="field"><span>Conditions (one per line; required for conditional)</span><textarea name="conditions"></textarea></label>
    <label class="field"><span>Short explanation *</span><textarea name="decision_note" required></textarea></label>
    <button class="primary" ${s(x.me?.id) === s(rv.reviewer_id) ? "" : "disabled"}>Record decision</button>${s(x.me?.id) === s(rv.reviewer_id) ? "" : html`<p class="muted" style="margin-top:10px">Only the assigned reviewer (${rv.reviewer_name ?? "unassigned"}) can decide.</p>`}</form>`
  : html`<p><span class="badge ${tone[s(rv.status)]}"><span class="dot"></span>${rv.status}</span> <span class="muted">${fmtLong(s(rv.decided_at))}</span></p><p style="margin:10px 0">${rv.decision_note}</p>
    ${conds.length ? html`<form method="post" action="/reviews/${rv.id}/conditions"><ul class="check">${conds.map((cd, i) => html`<li style="padding:4px 0"><label class="checkbox-label" style="margin:0"><input type="checkbox" name="done[]" value="${i}" ${cd.done ? "checked" : ""}>${cd.text}</label></li>`)}</ul><button style="margin-top:10px">Update conditions</button></form>` : ""}`}
  </div></section>
  </div></div>`;
}

// ---------------------------------------------------------------- Handoff (rendered by reference)
export function handoffPage(a: Row, rel: Related, ev: Evaluation, x: Ctx): H {
  const g = rel.agreements.find((k) => k.id === a.current_agreement_id);
  if (!g) return html`<a href="/accounts/${a.id}" class="back">← ${a.name}</a><h1>Handoff</h1><p class="muted">No accepted agreement yet.</p>`;
  const p = rel.proposals.find((k) => k.id === g.proposal_id)!, req = rel.requirements.find((k) => k.id === g.requirements_id);
  const h = rel.handoffs.find((k) => k.agreement_id === g.id);
  const ms = rel.tasks.filter((k) => k.type === "milestone");
  const canAccept = s(x.me?.id) === s(a.technical_owner_id);
  return html`<a href="/accounts/${a.id}?tab=delivery" class="back">← ${a.name}</a>
  <div class="account-heading"><div><h1>Handoff</h1><div class="sub">Agreement rev ${p.revision}, accepted ${fmtLong(s(g.accepted_at))} · ${g.acceptance_evidence}</div></div>
    ${h ? (h.accepted_at && !h.stale_reason ? html`<span class="badge green"><span class="dot"></span>Accepted ${fmtLong(s(h.accepted_at))} by ${h.accepted_by_name}</span>` : html`<span class="badge red"><span class="dot"></span>Awaiting acceptance</span>`) : ""}</div>
  <div class="grid2"><div>
  <section class="panel"><div class="section-header"><h2>Agreement</h2></div><div class="card-body"><dl class="facts single"><div><dt>Deliverables</dt><dd><pre class="wrap">${p.deliverables}</pre></dd></div><div><dt>Exclusions</dt><dd>${p.exclusions ?? "—"}</dd></div><div><dt>Price / payment</dt><dd>${p.price_terms ?? "—"}</dd></div><div><dt>Dates</dt><dd>${p.dates ?? "—"}</dd></div><div><dt>Customer responsibilities</dt><dd>${p.customer_responsibilities ?? "—"}</dd></div><div><dt>Success criterion</dt><dd>${p.success_metric} → ${p.success_target}${p.success_unit ?? ""} <span class="muted">(${p.success_direction} is better; basis ${p.success_basis ?? "unspecified"})</span></dd></div><div><dt>Data handling as agreed</dt><dd>${handlingText(handlingOf(p))}</dd></div><div><dt>Customer restrictions at acceptance</dt><dd>${req ? html`${req.restriction_status}${req.wording ? html` — <i>${req.wording}</i>` : ""}` : "not recorded"}</dd></div></dl></div></section>
  ${changedBeforeAcceptance(p, rel)}
  <section class="panel"><div class="section-header"><h2>People</h2></div><div class="card-body"><dl class="facts"><div><dt>Customer contact</dt><dd>${a.contact ?? "—"}</dd></div><div><dt>Buyer</dt><dd>${a.buyer ?? "—"}</dd></div><div><dt>Account owner</dt><dd>${a.owner_name}</dd></div><div><dt>Technical owner</dt><dd>${a.technical_owner_name ?? html`<span class="red">unassigned</span>`}</dd></div></dl></div></section>
  </div><div>
  <section class="panel"><div class="section-header"><h2>Acceptance</h2></div><div class="card-body">
  ${!h ? html`<p class="muted">Backfilled engagement: no handoff packet was generated in this system.</p>` : h.accepted_at && !h.stale_reason ? html`<p>Accepted ${fmtLong(s(h.accepted_at))} by ${h.accepted_by_name}.</p>${h.acceptance_note ? html`<blockquote style="margin-top:10px">${h.acceptance_note}</blockquote>` : ""}` : html`${h.stale_reason ? html`<div class="error">${h.stale_reason}</div>` : ""}<form method="post" action="/handoffs/${h.id}/accept"><label class="field"><span>Note</span><textarea name="note"></textarea></label><button class="primary" ${canAccept ? "" : "disabled"}>I accept this engagement as technical owner</button>${canAccept ? "" : html`<p class="muted" style="margin-top:10px">Only ${a.technical_owner_name ?? "the technical owner"} can accept. Switch role in the sidebar.</p>`}</form>`}</div></section>
  <section class="panel"><div class="section-header"><h2>Milestones <span class="count">${ms.length}</span></h2></div>${ms.length ? ms.map((k) => html`<div class="task-row ${k.status !== "open" ? "muted" : ""}"><div><div class="task-title">${k.title}</div><small>${k.owner_name ?? "unassigned"}${k.status !== "open" ? " · done" : ""}</small></div><span class="task-date">${fmtLong(s(k.due_date))}</span></div>`) : html`<div class="empty">None yet.</div>`}${h?.stale_reason ? html`<div class="card-body amber" style="padding-top:0">Amendment accepted: check whether these milestones need adjusting; nothing was changed automatically.</div>` : ""}</section>
  <section class="panel"><div class="section-header"><h2>Unresolved risks <span class="count">${ev.signals.length}</span></h2></div>${ev.signals.length ? ev.signals.map((sg) => html`<div class="risk-item"><div><span class="badge ${sg.severity === "warning" ? "amber" : "red"}"><span class="dot"></span>${SEVERITY_LABEL[sg.severity]}</span><p style="margin-top:8px">${sg.reason}</p></div></div>`) : html`<div class="empty">None flagged.</div>`}</section>
  </div></div>`;
}

// What the customer heard earlier but is not in the accepted text. Delivery should assume they may still expect it.
function changedBeforeAcceptance(p: Row, rel: Related): H {
  const earlier = rel.proposals.filter((k) => Number(k.revision) < Number(p.revision)).sort((x, y) => Number(x.revision) - Number(y.revision));
  if (!earlier.length) return html``;
  const first = earlier[0];
  const FIELDS: [string, string][] = [["deliverables", "Deliverables"], ["exclusions", "Exclusions"], ["price_terms", "Price / payment"], ["dates", "Dates"], ["customer_responsibilities", "Customer responsibilities"], ["success_metric", "Success metric"], ["success_target", "Target"]];
  const diffs = FIELDS.filter(([k]) => s(first[k]) !== s(p[k]));
  const notes = rel.proposals.filter((k) => Number(k.revision) > 1 && Number(k.revision) <= Number(p.revision) && k.change_note).sort((x, y) => Number(x.revision) - Number(y.revision));
  return html`<section class="panel"><div class="section-header"><h2>Changed before acceptance <span class="badge amber">rev 1 → rev ${p.revision}</span></h2></div><div class="card-body">
  ${notes.length ? html`<ul style="margin:0 0 14px;padding-left:18px">${notes.map((k) => html`<li>Rev ${k.revision}: ${k.change_note}</li>`)}</ul>` : ""}
  ${diffs.length ? html`<dl class="facts single">${diffs.map(([k, label]) => html`<div><dt>${label}</dt><dd><span class="muted">was:</span> ${s(first[k]) || "—"}<br><span class="muted">now:</span> ${s(p[k]) || "—"}</dd></div>`)}</dl>` : html`<p class="muted">No field differs from rev 1.</p>`}</div></section>`;
}

// Calibration: the expert grading session that defines "good" and produces the baseline. Shown pre- and post-sale.
function calibrationBlock(a: Row, rel: Related, x: Ctx): H {
  const id = s(a.id), ks = rel.calibrations ?? [];
  const o = rel.outcome;
  return html`<h2 id="calibration">Grading calibration</h2>
  ${ks.length ? html`<table><tr><th>When</th><th>Source</th><th>n</th><th>Agreement</th><th>Baseline</th><th>Failure categories</th><th></th></tr>${ks.map((k) => { const cats = parseJSON<{ label: string; count: number | null }[]>(k.failure_categories, []); const agr = k.agreement == null ? html`<span class="muted">no grader fitted</span>` : html`<span class="${Number(k.agreement) < CALIBRATION_MIN_AGREEMENT ? "amber" : "green"}">${k.agreement}%</span>`; return html`<tr><td class="nowrap">${fmt(k.created_at)}</td><td>${CALIBRATION_SOURCE[s(k.source)] ?? k.source}${k.source === "self_serve_samples" ? html` <span class="amber">(not production)</span>` : ""}<div class="small muted">${k.grader_version ?? ""}${k.expert ? html` · graded by ${k.expert}` : ""}</div></td><td>${k.n_examples}</td><td>${agr}</td><td>${k.baseline != null ? html`${k.baseline}${k.unit ?? ""} <span class="small muted">${k.metric ?? ""}</span>` : "—"}</td><td class="small">${cats.length ? cats.map((c) => `${c.label}${c.count != null ? ` ×${c.count}` : ""}`).join("; ") : "—"}${k.notes ? html`<div class="muted">${k.notes}</div>` : ""}</td><td class="small nowrap">${k.applied ? html`<span class="muted">in use</span>` : ""}</td></tr>`; })}</table>` : html`<p class="muted">No grading session recorded.</p>`}
  <details class="drawer"><summary>Record a grading session</summary><form method="post" action="/accounts/${id}/calibrations">
    <div class="row small"><label class="field"><span>Examples came from</span><select name="source"><option value="production_sample">production sample (under recorded restrictions)</option><option value="redacted_sample">redacted sample</option><option value="self_serve_samples">pasted samples (self-serve)</option></select></label><label class="field"><span>Examples graded</span><input name="n_examples" size="5"></label><label class="field"><span>Held-out agreement % (blank = no grader fitted)</span><input name="agreement" size="5"></label><label class="field" style="flex:2"><span>Grader version</span><input name="grader_version" placeholder="e.g. metagrader v1 (Trajectory)"></label></div>
    <div class="row small"><label class="field" style="flex:2"><span>Metric</span><input name="metric" value="${o?.metric ?? ""}" placeholder="e.g. Outputs rated unacceptable"></label><label class="field"><span>Baseline</span><input name="baseline" size="6"></label><label class="field"><span>Unit</span><input name="unit" value="${o?.unit ?? "%"}" size="4"></label><label class="field"><span>Direction</span><select name="direction"><option value="lower" ${o?.direction !== "higher" ? "selected" : ""}>lower is better</option><option value="higher" ${o?.direction === "higher" ? "selected" : ""}>higher is better</option></select></label><label class="field" style="flex:2"><span>Expert who graded</span><input name="expert"></label></div>
    <label class="field small"><span>Failure categories, one per line (optionally "label ×count")</span><textarea name="failure_categories" rows="3"></textarea></label>
    <label class="field small"><span>Notes (what was contested, what the sample excluded)</span><input name="notes" style="width:100%"></label>
    <label class="small"><input type="checkbox" name="apply" value="1"> Use this baseline as the success measurement for this account (replaces the current baseline; the basis records grader and sample)</label>
    <p><button class="primary">Save</button></p></form></details>`;
}

export { adminPage, gradeExamples, gradeResult, gradeStart, howAlertsWork } from "./views_public.ts";
